#[test]
fn test_arb_values_are_exact_minor_units() {
    let text: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let s27: i32 = oat_text_27(text);
    let s28: i32 = oat_text_28(text);
    let s29: i32 = oat_text_29(text);
    let s30: i32 = oat_text_30(text);
    let s31: i32 = oat_text_31(text);
    let s13: i32 = oat_text_13(text);
    let s43: i32 = oat_text_43(text);
    let s44: i32 = oat_text_44(text);
    let s45: i32 = oat_text_45(text);
    let s47: i32 = oat_text_47(text);
    let meta: &mut crate::port::Cells = &mut crate::port::Cells::new();
    crate::testport::assert_eq64(fmt_value(text, s27, 5, meta), 1230 as i64, "exact signed minor units");
    crate::testport::assert_eq(crate::port::cells_at(meta, 0), 1, "valid amount");
    crate::testport::assert_eq64(fmt_value(text, s28, 10, meta), -123450 as i64, "exact signed minor units");
    crate::testport::assert_eq(crate::port::cells_at(meta, 0), 1, "valid amount");
    crate::testport::assert_eq64(fmt_value(text, s29, 9, meta), -123450 as i64, "exact signed minor units");
    crate::testport::assert_eq(crate::port::cells_at(meta, 0), 1, "valid amount");
    crate::testport::assert_eq64(fmt_value(text, s30, 9, meta), -123450 as i64, "exact signed minor units");
    crate::testport::assert_eq(crate::port::cells_at(meta, 0), 1, "valid amount");
    crate::testport::assert_eq64(fmt_value(text, s31, 8, meta), 1230 as i64, "exact signed minor units");
    crate::testport::assert_eq(crate::port::cells_at(meta, 0), 1, "valid amount");
    crate::testport::assert_eq64(fmt_value(text, s13, 13, meta), 57985811 as i64, "exact signed minor units");
    crate::testport::assert_eq(crate::port::cells_at(meta, 0), 1, "valid amount");
    crate::testport::assert_eq64(fmt_value(text, s43, 12, meta), 123456789 as i64, "exact signed minor units");
    crate::testport::assert_eq(crate::port::cells_at(meta, 0), 1, "valid amount");
    crate::testport::assert_eq64(fmt_value(text, s44, 4, meta), 1 as i64, "exact signed minor units");
    crate::testport::assert_eq(crate::port::cells_at(meta, 0), 1, "valid amount");
    crate::testport::assert_eq64(fmt_value(text, s45, 5, meta), -1 as i64, "exact signed minor units");
    crate::testport::assert_eq(crate::port::cells_at(meta, 0), 1, "valid amount");
    crate::testport::assert_eq64(fmt_value(text, s47, 6, meta), 1230 as i64, "exact signed minor units");
    crate::testport::assert_eq(crate::port::cells_at(meta, 0), 1, "valid amount");
    crate::testport::assert_eq(crate::port::cells_at(meta, 1), 2, "decimal places are recorded");
}
