#[test]
fn test_arb_band_numbers_and_ties_are_held() {
    crate::testport::assert_eq(oa_band_word(1, 4, 1, 0), 0, "numbers held even with unanimous agreement");
    crate::testport::assert_eq(oa_band_word(0, 2, 1, 0), 1, "dictionary word agreed by two views");
    crate::testport::assert_eq(oa_band_word(0, 3, 0, 0), 1, "three views agree on a lexical form");
    crate::testport::assert_eq(oa_band_word(0, 3, 1, 1), 0, "tie blocks");
    crate::testport::assert_eq(oa_band_rule(2, 0, 900), 0, "at least three accepted words");
    crate::testport::assert_eq(oa_band_rule(5, 1, 900), 0, "one unagreed lexical word blocks the band");
    crate::testport::assert_eq(oa_band_rule(5, 0, 599), 0, "at least sixty percent coverage");
    crate::testport::assert_eq(oa_band_rule(5, 0, 600), 1, "coverage boundary");
}
#[test]
fn test_arb_view_budget_and_integer_factor() {
    crate::testport::assert_eq(oa_view_factor(7, 36), 5, "seven pixel text gets integer x5");
    crate::testport::assert_eq(oa_view_factor(1, 36), 6, "upscale cap");
    crate::testport::assert_eq(oa_view_factor(40, 36), 1, "no downscale");
    crate::testport::assert_eq(oa_view_allowed(0, 0, 0), 0, "born digital cannot request arbitration");
    crate::testport::assert_eq(oa_view_allowed(1, 0, 3), 1, "last table view");
    crate::testport::assert_eq(oa_view_allowed(1, 0, 4), 0, "two tables times two views");
    crate::testport::assert_eq(oa_view_allowed(1, 1, 11), 1, "last band view");
    crate::testport::assert_eq(oa_view_allowed(1, 1, 12), 0, "three bands times four views");
    crate::testport::assert_eq(oa_active(), 0, "bulk arbitration stays off; the separate percent sign path is bounded in oapct");
}
